import axios from 'axios';
import { createContext, useContext, useState } from 'react';
import jwtDecode from 'jwt-decode';

const AuthContext = createContext();
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(() => {
    const token = localStorage.getItem('token');
    if (!token) return null;
    try {
      return jwtDecode(token); // Decodifica el token directamente
    } catch {
      return null;
    }
  });

  const login = async (correo, password) => {
    try {
      const res = await axios.post('http://localhost:5000/auth/login', { correo, password });
      
      // Asegúrate de que el backend devuelve lo siguiente:
      const { access_token, usuario } = res.data;

      if (!access_token || !usuario) {
        throw new Error('No se recibió un token válido');
      }

      // Guardamos el token y los datos del usuario
      localStorage.setItem('token', access_token);
      localStorage.setItem('usuario', JSON.stringify(usuario));

      // Decodificamos el token y asignamos el rol correctamente
      const decodedUser = jwtDecode(access_token);
      setCurrentUser(decodedUser);

      return usuario;
    } catch (err) {
      throw err;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('usuario');
    setCurrentUser(null);
  };

  return (
    <AuthContext.Provider value={{ currentUser, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}
